def patch_file(path, ids):
    s = open(path, encoding="utf-8").read()
    for cid in ids:
        m = re.search(r'  \{\n    id: "%s".*?\n  \},\n' % cid, s, re.S)
        if not m:
            print(f"NOT FOUND {cid} in {path}"); sys.exit(1)
        s = s[:m.start()] + NEW[cid] + "\n" + s[m.end():]
    open(path, "w", encoding="utf-8").write(s)
    print(f"ok {path}: {len(ids)} cases")

